insert into public.daily_questions (id, prompt, category, status, room) values ('6bfe5fb1-b37c-4fc9-b16a-16a5fe73ab01', 'Your friend throws a party and invites everybody in the group chat except you. Two days later, they text, "Hey stranger!" What''s your move?', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('6abc7cc8-5243-45a0-bda4-00cc7ebaf667', '6bfe5fb1-b37c-4fc9-b16a-16a5fe73ab01', 1, '"So we''re just pretending the party didn''t happen?"', 'Apparently, you''ve brought the elephant into the room, pulled out a chair, and asked it to explain itself.', '[{"pole":"direct_indirect:positive","points":3},{"pole":"conflict_peacekeeping:positive","points":2},{"pole":"accountability_defensiveness:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('b84a890f-4fb7-469b-8d22-3f6c1a2cd745', '6bfe5fb1-b37c-4fc9-b16a-16a5fe73ab01', 2, '"Heyyy!" I''m acting normal while I figure out what''s going on.', 'Apparently, the friendship is under investigation. The suspect has not been notified.', '[{"pole":"social_attunement:positive","points":2},{"pole":"trust_verify:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('d76e7895-d8f8-4920-8282-0337d80c2149', '6bfe5fb1-b37c-4fc9-b16a-16a5fe73ab01', 3, 'I respond normally. Not every event needs my name on the guest list.', 'Apparently, your self-worth doesn''t come with an RSVP requirement. Look at you, emotionally employed.', '[{"pole":"self_secure_reassurance:positive","points":2},{"pole":"independent_collaborative:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('24cfddca-b52a-47c4-8de0-d108c93f1fed', '6bfe5fb1-b37c-4fc9-b16a-16a5fe73ab01', 4, 'I don''t respond. They can enjoy that same exclusive energy.', 'Apparently, you''ve launched your own private event. It''s called Access Revoked, and attendance is extremely limited.', '[{"pole":"boundary_holding_approval_seeking:positive","points":2},{"pole":"duty_first_self_preserving:negative","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('4b74a183-84b6-4971-92ed-04ddf7e01b7e', 'Your single friend, whose dating life is a five-season disaster, starts giving you relationship advice. What are you thinking?', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('f7c7c72f-fb83-4bd9-8085-91bf554b0e40', '4b74a183-84b6-4971-92ed-04ddf7e01b7e', 1, '"Interesting advice from someone whose love life needs a fire extinguisher."', 'Apparently, you''re having trouble hearing the sermon over the sound of the preacher''s house burning down.', '[{"pole":"tactful_blunt:negative","points":3},{"pole":"playful_serious:positive","points":2},{"pole":"supportive_challenging:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('2ce98f98-f9d6-4869-bba9-6efd033b5e49', '4b74a183-84b6-4971-92ed-04ddf7e01b7e', 2, 'Sometimes people give good advice they don''t follow themselves.', 'Apparently, you can separate the message from the messenger. Even when the messenger is a walking cautionary tale.', '[{"pole":"perspective_taking_self_referencing:positive","points":2},{"pole":"reflective_reactive:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('c8a804c6-12e8-49ca-bd45-51932145c687', '4b74a183-84b6-4971-92ed-04ddf7e01b7e', 3, 'I''m listening, but I''m absolutely fact-checking the source.', 'Apparently, you''re accepting relationship advice with the same confidence you''d give a restaurant with seventeen health violations.', '[{"pole":"trust_verify:negative","points":2},{"pole":"practical_idealistic:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('8d50b2a6-047f-4c3f-bde4-3398b7a6930d', '4b74a183-84b6-4971-92ed-04ddf7e01b7e', 4, 'I''m asking follow-up questions. Maybe they''ve learned something from all that chaos.', 'Apparently, you see five failed relationships and think, "Excellent. A longitudinal study."', '[{"pole":"curious_decisive:positive","points":2},{"pole":"private_open:negative","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('33dda90b-2560-4989-96ac-711cdc9152aa', 'You ordered a salad and water. Everybody else ordered steak, cocktails, and dessert. Somebody says, "Let''s just split the bill evenly."', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('fa7bd32c-a8e8-46f2-b41f-3eaacd25899b', '33dda90b-2560-4989-96ac-711cdc9152aa', 1, '"Absolutely not. My lettuce is not financing your lobster."', 'Apparently, you''re happy to split the friendship. The check, however, will be itemized.', '[{"pole":"direct_indirect:positive","points":3},{"pole":"boundary_holding_approval_seeking:positive","points":3},{"pole":"practical_idealistic:positive","points":2},{"pole":"tactful_blunt:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('a82d6f32-20c6-4ba3-a555-d3c89083b4fb', '33dda90b-2560-4989-96ac-711cdc9152aa', 2, 'I''ll pay this time, but we''re never doing this again.', 'Apparently, you just purchased a $94 salad and a valuable lesson about group dining.', '[{"pole":"conflict_peacekeeping:negative","points":2},{"pole":"forgiving_receipts:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('5fe28931-78db-4949-b3a8-37b693ae4d48', '33dda90b-2560-4989-96ac-711cdc9152aa', 3, 'I''ll quietly ask the server for separate checks.', 'Apparently, you''ve found a solution that requires neither confrontation nor sponsorship of somebody else''s filet mignon.', '[{"pole":"practical_idealistic:positive","points":2},{"pole":"tactful_blunt:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('83778247-3a13-4b04-814c-b4655d835119', '33dda90b-2560-4989-96ac-711cdc9152aa', 4, 'I don''t mind. It all balances out eventually.', 'Apparently, you''re trusting the universe to reimburse you in appetizers. Bold financial strategy.', '[{"pole":"gives_freely_keeps_score:positive","points":2},{"pole":"control_allowing:negative","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('3fe375c0-94f4-4801-b030-7f7b55c625bb', 'Someone texts, "I''m outside!" You didn''t invite anybody over. What''s happening next?', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('25db640a-ff2c-438e-b220-99eb7631e17f', '3fe375c0-94f4-4801-b030-7f7b55c625bb', 1, 'I''m opening the door. Come on in!', 'Apparently, your home has an unofficial revolving-door policy. Hospitality has defeated the concept of notice.', '[{"pole":"planner_spontaneous:negative","points":3},{"pole":"private_open:negative","points":3},{"pole":"initiating_responsive:negative","points":2},{"pole":"trust_verify:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('ef98f5c1-e14f-4be6-a79d-22cbd43a0369', '3fe375c0-94f4-4801-b030-7f7b55c625bb', 2, '"Outside where? Because surely not MY house."', 'Apparently, your front porch isn''t a public attraction. Visiting hours require prior authorization.', '[{"pole":"boundary_holding_approval_seeking:positive","points":2},{"pole":"direct_indirect:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('3751f4fd-9041-447a-b02f-c54089a2b85b', '3fe375c0-94f4-4801-b030-7f7b55c625bb', 3, 'I''m checking who''s outside before deciding.', 'Apparently, you need a name, a reason, and possibly a witness before unlocking anything.', '[{"pole":"trust_verify:negative","points":2},{"pole":"practical_idealistic:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('4e2d204a-8ac3-45c3-aaea-607b23be1907', '3fe375c0-94f4-4801-b030-7f7b55c625bb', 4, 'I''m pretending I''m not home. Even if my car is in the driveway.', 'Apparently, your vehicle is home. You, unfortunately, are unavailable for comment.', '[{"pole":"private_open:positive","points":2},{"pole":"duty_first_self_preserving:negative","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('743c4c2e-1e58-44d7-892f-abf2016b4742', 'Somebody sends a shady message to the group chat, then immediately deletes it. What''s your reaction?', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('e72f5238-1402-4798-a469-549c0e25f428', '743c4c2e-1e58-44d7-892f-abf2016b4742', 1, '"Too late. I saw it. Let''s discuss."', 'Apparently, deleting the message only removed the evidence from your screen. Your memory has cloud backup.', '[{"pole":"direct_indirect:positive","points":3},{"pole":"conflict_peacekeeping:positive","points":3},{"pole":"accountability_defensiveness:positive","points":1},{"pole":"forgiving_receipts:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('a9378267-c3c8-447b-aae1-f954b7ab2b2b', '743c4c2e-1e58-44d7-892f-abf2016b4742', 2, 'I''m asking what happened. I need context.', 'Apparently, you refuse to solve a mystery with half the clues. The group chat will remain in session.', '[{"pole":"curious_decisive:positive","points":2},{"pole":"trust_verify:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('7b847915-622f-48bf-b14d-4d7233725bec', '743c4c2e-1e58-44d7-892f-abf2016b4742', 3, 'I''m saying nothing, but I took a screenshot.', 'Apparently, the message was deleted from the chat, not from the archives of the Department of You.', '[{"pole":"social_attunement:positive","points":2},{"pole":"planner_spontaneous:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('b3662463-2e33-43de-b1ac-fab1db8dc5fd', '743c4c2e-1e58-44d7-892f-abf2016b4742', 4, 'Nothing. They deleted it, so I''m letting it go.', 'Apparently, you''ve decided not every deleted message deserves a congressional hearing. Remarkable restraint.', '[{"pole":"conflict_peacekeeping:negative","points":2},{"pole":"control_allowing:negative","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('ce1d5653-6d34-46ec-89eb-aa3ed055f5eb', 'It''s your birthday. Which one sounds like the best celebration?', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('3e50e621-b9c5-4d28-a784-8fe837de2cf2', 'ce1d5653-6d34-46ec-89eb-aa3ed055f5eb', 1, 'A huge surprise party where everybody shows up for me.', 'Apparently, you want the room full, the cameras rolling, and at least three people crying during the speeches.', '[{"pole":"private_open:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('9372fe5a-01ee-4ffa-855f-7b6190009646', 'ce1d5653-6d34-46ec-89eb-aa3ed055f5eb', 2, 'A luxury trip with absolutely no responsibilities.', 'Apparently, another year older means another year less interested in doing dishes on your birthday.', '[{"pole":"adventure_comfort:positive","points":2},{"pole":"adventure_comfort:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('7e7491fc-53a3-42cb-9790-24766879adcd', 'ce1d5653-6d34-46ec-89eb-aa3ed055f5eb', 3, 'A quiet day doing exactly what I want.', 'Apparently, the greatest gift anyone can give you is the freedom to be unavailable.', '[{"pole":"independent_collaborative:positive","points":2},{"pole":"adventure_comfort:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('0d721828-c55e-48a6-a40b-6c3876a52cdb', 'ce1d5653-6d34-46ec-89eb-aa3ed055f5eb', 4, 'Something thoughtful with my favorite people.', 'Apparently, you don''t need the whole city celebrating. Just the people who actually know how you take your coffee.', '[{"pole":"sentimental_thick_skinned:positive","points":2}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('9009e45e-8787-4f3a-ac98-1468c0dbf73d', 'Someone says, "You look SO much better than you used to!" How are you taking that?', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('1eda43e1-c957-4caa-ab3d-a035ef39be40', '9009e45e-8787-4f3a-ac98-1468c0dbf73d', 1, '"Thank you… wait. What was wrong with me before?"', 'Apparently, you received the compliment, located the hidden insult, and would now like a full explanation.', '[{"pole":"social_attunement:positive","points":3},{"pole":"curious_decisive:positive","points":2},{"pole":"direct_indirect:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('81ccae4a-023e-4743-9e0c-750f65761d1f', '9009e45e-8787-4f3a-ac98-1468c0dbf73d', 2, '"I know, right? The upgrade is undeniable."', 'Apparently, your confidence didn''t even allow the insult to clear customs. Only the compliment was admitted.', '[{"pole":"self_secure_reassurance:positive","points":3}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('227bd40a-d5fd-409d-a773-7aed51c111fd', '9009e45e-8787-4f3a-ac98-1468c0dbf73d', 3, 'I laugh it off. They probably meant well.', 'Apparently, you''ve chosen to assume good intentions. The accidental roast has been pardoned.', '[{"pole":"perspective_taking_self_referencing:positive","points":3},{"pole":"emotional_intensity:negative","points":2},{"pole":"forgiving_receipts:positive","points":1},{"pole":"sentimental_thick_skinned:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('94875b11-2d39-425e-9cab-45285579a5fb', '9009e45e-8787-4f3a-ac98-1468c0dbf73d', 4, '"That was a weird way to compliment somebody."', 'Apparently, you''re accepting the praise but returning the packaging. Please try again with less disrespect.', '[{"pole":"direct_indirect:positive","points":2},{"pole":"boundary_holding_approval_seeking:positive","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('931830c0-7264-423e-a256-86c882eb9e6b', 'You win $10 million tomorrow. What''s the FIRST thing you''re doing?', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('eb49ae86-1b66-4571-ae16-1d931e21288e', '931830c0-7264-423e-a256-86c882eb9e6b', 1, 'Calling a financial advisor. Nobody is touching a dollar yet.', 'Apparently, you''ve become a millionaire and immediately scheduled a meeting. Even your fantasies have spreadsheets.', '[{"pole":"planner_spontaneous:positive","points":3},{"pole":"practical_idealistic:positive","points":3},{"pole":"trust_verify:negative","points":2},{"pole":"duty_first_self_preserving:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('2321e31b-994a-4fc1-869b-86179bc1691d', '931830c0-7264-423e-a256-86c882eb9e6b', 2, 'Booking the most ridiculous vacation of my life.', 'Apparently, you''ve been rich for twelve minutes and already need a passport extension.', '[{"pole":"adventure_comfort:positive","points":2},{"pole":"planner_spontaneous:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('72640422-be54-41d7-8ffa-ebd60acc745b', '931830c0-7264-423e-a256-86c882eb9e6b', 3, 'Taking care of the people I love.', 'Apparently, your first luxury purchase is somebody else''s peace of mind. That''s a pretty expensive love language.', '[{"pole":"supportive_challenging:positive","points":2},{"pole":"gives_freely_keeps_score:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('288e16a3-5cd3-4f2f-88ff-75342db69ec6', '931830c0-7264-423e-a256-86c882eb9e6b', 4, 'Telling absolutely nobody. I''m going to work like nothing happened.', 'Apparently, you''re sitting in a meeting worth eight figures and still pretending to care about the office printer.', '[{"pole":"private_open:positive","points":2},{"pole":"control_allowing:positive","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('e2744518-c28c-4c57-86d7-8c1a34a8d803', 'Someone cuts in front of you after you''ve been waiting in line for 25 minutes. What happens?', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('3f956fd3-56d2-4c49-9bef-9ed7199f7570', 'e2744518-c28c-4c57-86d7-8c1a34a8d803', 1, '"Excuse me. The line starts back there."', 'Apparently, you didn''t spend 25 minutes developing a relationship with this floor tile just to be disrespected.', '[{"pole":"direct_indirect:positive","points":3},{"pole":"rules_bending:positive","points":3},{"pole":"boundary_holding_approval_seeking:positive","points":2},{"pole":"conflict_peacekeeping:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('28599f65-bd5e-43e8-9c67-cd8713479a2b', 'e2744518-c28c-4c57-86d7-8c1a34a8d803', 2, 'I let it go. I''m not ruining my day over one person.', 'Apparently, your peace costs more than 25 minutes. Congratulations, you''ve priced yourself out of unnecessary drama.', '[{"pole":"conflict_peacekeeping:negative","points":2},{"pole":"emotional_intensity:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('2f7e2ca0-2e84-4742-9ca9-69e0df1a4baf', 'e2744518-c28c-4c57-86d7-8c1a34a8d803', 3, 'I look around to see if anybody else noticed.', 'Apparently, before you confront the defendant, you''d like to know whether the jury witnessed the crime.', '[{"pole":"social_attunement:positive","points":2},{"pole":"trust_verify:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('40a9ef68-acb0-47f0-a754-65804104dfd3', 'e2744518-c28c-4c57-86d7-8c1a34a8d803', 4, 'I tell the employee managing the line.', 'Apparently, you''re not arguing with strangers when there''s a perfectly good manager available to enforce civilization.', '[{"pole":"rules_bending:positive","points":2},{"pole":"practical_idealistic:positive","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('20c8827d-88ac-4f74-b156-d1a0d3ed2cff', 'You notice somebody who never likes your posts watches EVERY story you upload. What''s your theory?', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('efdd4d94-dc77-4654-97d4-7184e35ad8f7', '20c8827d-88ac-4f74-b156-d1a0d3ed2cff', 1, 'They''re nosy. Welcome to the fan club.', 'Apparently, you have a silent subscriber. No likes, no comments, just perfect attendance.', '[{"pole":"playful_serious:positive","points":2},{"pole":"social_attunement:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('c63898fb-2630-4bf7-b306-073b68fc5503', '20c8827d-88ac-4f74-b156-d1a0d3ed2cff', 2, 'Maybe they just enjoy watching stories. It''s not that deep.', 'Apparently, you''ve decided not to turn Instagram analytics into a psychological thriller.', '[{"pole":"social_attunement:negative","points":2},{"pole":"emotional_intensity:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('988a967b-f926-46d8-9298-557e688c0c84', '20c8827d-88ac-4f74-b156-d1a0d3ed2cff', 3, 'I''m checking their profile. Let''s see who''s studying whom.', 'Apparently, the surveillance department has detected suspicious activity and launched a reciprocal investigation.', '[{"pole":"curious_decisive:positive","points":2},{"pole":"trust_verify:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('16b7e56c-8ef2-496a-8b79-9e7d3166287c', '20c8827d-88ac-4f74-b156-d1a0d3ed2cff', 4, 'I don''t care. My content is public for a reason.', 'Apparently, your audience is welcome to lurk, observe, and take notes. The show goes on.', '[{"pole":"self_secure_reassurance:positive","points":2},{"pole":"independent_collaborative:positive","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('ba87da5d-ade8-4f97-a944-265d55227a7a', 'Your favorite politician gets caught doing the EXACT thing they''ve been criticizing everyone else for. What''s your reaction?', 'Unsorted', 'Approved', 'private');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('04597651-65c0-4e21-961f-e31ff19c7a1b', 'ba87da5d-ade8-4f97-a944-265d55227a7a', 1, 'Oh, we''re definitely talking about this. Same rules for everybody.', 'Apparently, your standards don''t change depending on who''s standing at the podium. How inconvenient for the hypocrites.', '[{"pole":"accountability_defensiveness:positive","points":3},{"pole":"direct_indirect:positive","points":2},{"pole":"rules_bending:positive","points":2},{"pole":"conflict_peacekeeping:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('f42b0993-68da-45f6-8663-10015faf73c2', 'ba87da5d-ade8-4f97-a944-265d55227a7a', 2, 'I need the whole story. Headlines have a way of leaving things out.', 'Apparently, you prefer facts over a good scandal. The internet finds that deeply inconvenient.', '[{"pole":"trust_verify:negative","points":3},{"pole":"reflective_reactive:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('f3b7ac6c-b577-48cc-9ceb-611668cfd19e', 'ba87da5d-ade8-4f97-a944-265d55227a7a', 3, 'I''m disappointed, but I''m not handing the other side a victory lap.', 'Apparently, your principles are having a disagreement with your loyalty. And loyalty has requested that this conversation remain private.', '[{"pole":"protective_hands_off:positive","points":2},{"pole":"private_open:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('b3769e29-d571-4cde-b2a5-234132657d7c', 'ba87da5d-ade8-4f97-a944-265d55227a7a', 4, 'Honestly? They''re all hypocrites. Why is anybody surprised?', 'Apparently, your expectations for politicians are so low they''re practically underground. At least nobody can accuse you of being easily disappointed.', '[{"pole":"practical_idealistic:positive","points":2},{"pole":"sentimental_thick_skinned:negative","points":1}]'::jsonb);
