insert into public.daily_questions (id, prompt, category, status, room) values ('1045dfda-7787-4529-81d6-1406bf0636d0', 'You tell somebody they hurt your feelings. Their response? "Well, I''m sorry you feel that way."', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('a4ecc408-7326-445e-9e0f-375208772a56', '1045dfda-7787-4529-81d6-1406bf0636d0', 1, '"That''s not an apology. Try again."', 'Apparently, you''ve rejected the apology package. Please resubmit with actual accountability attached.', '[{"pole":"direct_indirect:positive","points":3},{"pole":"accountability_defensiveness:positive","points":3},{"pole":"boundary_holding_approval_seeking:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('bb6504b6-650f-4a8b-8b86-a5e0eed57332', '1045dfda-7787-4529-81d6-1406bf0636d0', 2, '"Maybe I''m being too sensitive."', 'Apparently, somebody handed you a non-apology and you immediately started investigating yourself. Interesting customer-service policy.', '[{"pole":"perspective_taking_self_referencing:negative","points":2},{"pole":"self_secure_reassurance:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('916ae3a7-05b7-41a4-8216-56e04d9acc64', '1045dfda-7787-4529-81d6-1406bf0636d0', 3, '"Forget it." I''m done explaining.', 'Apparently, you''ve closed the complaint department. Management will not be responding to further inquiries.', '[{"pole":"vulnerable_armored:negative","points":2},{"pole":"duty_first_self_preserving:negative","points":2},{"pole":"boundary_holding_approval_seeking:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('94f36a56-3bdd-4b67-8ff3-2f998833652c', '1045dfda-7787-4529-81d6-1406bf0636d0', 4, '"I don''t think you understand why I''m upset."', 'Apparently, you''ve scheduled a second emotional briefing. The first one clearly went over somebody''s head.', '[{"pole":"repair_punishing:positive","points":3},{"pole":"direct_indirect:positive","points":2},{"pole":"patient_urgent:positive","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('1a7f6479-c3fa-43d1-ada6-9c5d0c0570fb', 'Your friend asks for your honest opinion on an outfit. It''s terrible.', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('51b72cbb-c813-483c-bf65-e2a1cd679f89', '1a7f6479-c3fa-43d1-ada6-9c5d0c0570fb', 1, '"Absolutely not. Go change."', 'Apparently, your friendship comes with free fashion emergencies and absolutely no return policy on the truth.', '[{"pole":"tactful_blunt:negative","points":3},{"pole":"direct_indirect:positive","points":3},{"pole":"supportive_challenging:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('472b81bb-2fe9-4dd3-bd46-34b8c2b3f3c1', '1a7f6479-c3fa-43d1-ada6-9c5d0c0570fb', 2, '"It''s not my favorite. What else do you have?"', 'Apparently, you''ve delivered the truth in protective packaging. Customer satisfaction remains surprisingly high.', '[{"pole":"tactful_blunt:positive","points":3},{"pole":"direct_indirect:positive","points":2},{"pole":"supportive_challenging:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('242ba84e-764d-4399-9b75-4235ecb49d74', '1a7f6479-c3fa-43d1-ada6-9c5d0c0570fb', 3, '"If YOU love it, that''s what matters."', 'Apparently, you''ve decided fashion crimes are outside your jurisdiction. The defendant looks thrilled.', '[{"pole":"protective_hands_off:negative","points":2},{"pole":"boundary_holding_approval_seeking:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('a5b375a2-6d78-47d5-8f65-51bdb6ec0f87', '1a7f6479-c3fa-43d1-ada6-9c5d0c0570fb', 4, '"Where are we going? Because that changes everything."', 'Apparently, the outfit has been placed on hold pending additional evidence. Fashion court is now in session.', '[{"pole":"practical_idealistic:positive","points":3},{"pole":"curious_decisive:positive","points":2},{"pole":"trust_verify:negative","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('8990c3c0-1602-4da8-964f-abf0c6615ee9', 'You accidentally break something expensive at somebody''s house. They haven''t noticed.', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('79f910d1-ecdd-4a18-9fec-685bf3280df5', '8990c3c0-1602-4da8-964f-abf0c6615ee9', 1, 'Tell them immediately and offer to replace it.', 'Apparently, you''ve confessed before the investigation even started. The insurance adjuster appreciates your cooperation.', '[{"pole":"accountability_defensiveness:positive","points":3},{"pole":"direct_indirect:positive","points":3},{"pole":"duty_first_self_preserving:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('b92b74c5-b1e7-4d71-86b5-2fa5cbb99a07', '8990c3c0-1602-4da8-964f-abf0c6615ee9', 2, 'Try to fix it first, then tell them.', 'Apparently, you''ve opened an unauthorized repair shop in somebody else''s living room. Business is not going well.', '[{"pole":"practical_idealistic:positive","points":2},{"pole":"duty_first_self_preserving:negative","points":1},{"pole":"accountability_defensiveness:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('d05fc76c-3667-453b-ae54-16d05ec77f25', '8990c3c0-1602-4da8-964f-abf0c6615ee9', 3, '"Are you SURE that wasn''t already broken?"', 'Apparently, you''ve arrived at the scene of your own crime and immediately requested a second opinion.', '[{"pole":"accountability_defensiveness:negative","points":3},{"pole":"duty_first_self_preserving:negative","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('807fe2e3-33c8-4835-80d7-e7d47c2eb545', '8990c3c0-1602-4da8-964f-abf0c6615ee9', 4, 'Quietly put it back and hope nobody touches it.', 'Apparently, you''ve chosen the ancient repair technique known as Moving It Two Inches to the Left.', '[{"pole":"duty_first_self_preserving:negative","points":3},{"pole":"direct_indirect:negative","points":2},{"pole":"vulnerable_armored:negative","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('38f9eca3-9845-45ad-aeed-683c4a0ab35a', 'You post a picture you LOVE. Somebody comments, "That''s the one you picked?"', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('b9a3b90e-8ea0-4915-9d93-6869d7bd408b', '38f9eca3-9845-45ad-aeed-683c4a0ab35a', 1, '"Yep. And I''d pick it again."', 'Apparently, your confidence has reviewed the complaint and found absolutely nothing requiring correction.', '[{"pole":"self_secure_reassurance:positive","points":3},{"pole":"direct_indirect:positive","points":2},{"pole":"sentimental_thick_skinned:negative","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('e92d0df4-a81e-4397-bb03-9f01d8eea2e9', '38f9eca3-9845-45ad-aeed-683c4a0ab35a', 2, 'Delete it. Maybe it wasn''t that cute.', 'Apparently, one unsolicited comment just overruled an entire photoshoot. The committee is ruthless.', '[{"pole":"boundary_holding_approval_seeking:negative","points":3},{"pole":"self_secure_reassurance:negative","points":2},{"pole":"reflective_reactive:negative","points":1}]'::jsonb);
