insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('e073389e-3f0f-4634-b0f3-0e4ee991cc10', '38f9eca3-9845-45ad-aeed-683c4a0ab35a', 4, '"And that''s why nobody asked you."', 'Apparently, you''ve reminded the audience that the comment section is not an elected governing body.', '[{"pole":"tactful_blunt:negative","points":3},{"pole":"boundary_holding_approval_seeking:positive","points":2},{"pole":"reflective_reactive:negative","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('00707a03-cc80-4760-8e3d-973bf3052f4c', 'You get invited to a fancy event. Dress code says "formal." You own absolutely nothing formal.', 'Unsorted', 'Approved', 'public');
