insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('3506cc84-124d-4b96-891d-531248403666', '00707a03-cc80-4760-8e3d-973bf3052f4c', 2, 'Borrow something. I''m not spending $300 to eat chicken.', 'Apparently, you''ve successfully negotiated luxury attendance at an extremely reasonable operating cost.', '[{"pole":"practical_idealistic:positive","points":3}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('a16a39b9-81f3-4d83-aa36-8b45a40b2f13', '00707a03-cc80-4760-8e3d-973bf3052f4c', 3, 'Wear my nicest outfit and hope for the best.', 'Apparently, you''ve interpreted formal as "I made an effort, and that''s between me and the Lord."', '[{"pole":"rules_bending:negative","points":2},{"pole":"control_allowing:negative","points":2}]'::jsonb);
