insert into public.daily_questions (id, prompt, category, status, room) values ('19f87587-bae9-4ad2-985e-904302e6e138', 'Somebody asks you to lead a project you''ve NEVER done before.', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('2ceb4357-f0e5-45d0-942e-8f9c9737fe78', '19f87587-bae9-4ad2-985e-904302e6e138', 1, '"Absolutely. I''ll figure it out."', 'Apparently, your qualifications include confidence, Wi-Fi, and a willingness to Google aggressively.', '[{"pole":"adventure_comfort:positive","points":3},{"pole":"initiating_responsive:positive","points":3},{"pole":"self_secure_reassurance:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('72e3ad8f-c1fd-43bc-8444-2db237a86beb', '19f87587-bae9-4ad2-985e-904302e6e138', 2, '"Can I shadow somebody first?"', 'Apparently, you''ve requested the tutorial before entering boss level. Sensible gaming strategy.', '[{"pole":"trust_verify:negative","points":2},{"pole":"independent_collaborative:negative","points":2},{"pole":"practical_idealistic:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('0db81f69-0ffe-4634-bf21-390ea5dcf325', '19f87587-bae9-4ad2-985e-904302e6e138', 3, '"Why me? There are people way more qualified."', 'Apparently, you''ve received an opportunity and immediately submitted a list of reasons somebody else deserves it.', '[{"pole":"self_secure_reassurance:negative","points":2},{"pole":"boundary_holding_approval_seeking:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('14e2b64a-e133-4ea8-9719-bbb23740309e', '19f87587-bae9-4ad2-985e-904302e6e138', 4, '"Only if I get to build my own team."', 'Apparently, you''ve accepted the assignment and immediately started your own little corporate empire.', '[{"pole":"control_allowing:positive","points":3},{"pole":"independent_collaborative:negative","points":2},{"pole":"planner_spontaneous:positive","points":1},{"pole":"initiating_responsive:positive","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('05d2249b-cb11-468c-98ea-ad22bf3384d2', 'Your friend gets an opportunity you''ve been working toward for YEARS.', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('e4f64e27-fae8-455e-8bd3-8ef31fc73ac1', '05d2249b-cb11-468c-98ea-ad22bf3384d2', 1, 'Celebrate them. My turn will come.', 'Apparently, you''re throwing confetti while your own dreams wait patiently in the parking lot. That''s range.', '[{"pole":"supportive_challenging:positive","points":3},{"pole":"practical_idealistic:negative","points":2},{"pole":"patient_urgent:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('8e6a1e77-a683-4c14-a3ec-d920a5f1ea81', '05d2249b-cb11-468c-98ea-ad22bf3384d2', 2, 'I''m happy for them AND a little jealous.', 'Apparently, two emotions have checked into the same hotel room. Neither one plans to leave.', '[{"pole":"vulnerable_armored:positive","points":3},{"pole":"emotional_intensity:positive","points":1},{"pole":"reflective_reactive:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('e33bc645-00c2-4434-a924-471559a0c58f', '05d2249b-cb11-468c-98ea-ad22bf3384d2', 3, 'Ask what they did differently. I need the blueprint.', 'Apparently, somebody else''s breakthrough has become your unauthorized professional development seminar.', '[{"pole":"ambitious_content:positive","points":3},{"pole":"curious_decisive:positive","points":3},{"pole":"practical_idealistic:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('ab66c208-81a1-4bc3-b884-2578354fcfd0', '05d2249b-cb11-468c-98ea-ad22bf3384d2', 4, 'Take a little space. I need to process.', 'Apparently, you''re happy for them, but your feelings have requested a separate dressing room.', '[{"pole":"reflective_reactive:positive","points":3},{"pole":"boundary_holding_approval_seeking:positive","points":2},{"pole":"duty_first_self_preserving:negative","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('58812704-45a7-48c0-87e6-8e7ad42b49fe', 'Your family says, "You''re different now that you''re doing better."', 'Unsorted', 'Approved', 'public');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('8d422b20-bac2-47c2-b231-1aa6b8857344', '58812704-45a7-48c0-87e6-8e7ad42b49fe', 1, '"That''s kind of the point. Growth changes people."', 'Apparently, you''ve upgraded your operating system and some relatives are demanding the old version.', '[{"pole":"self_secure_reassurance:positive","points":3},{"pole":"independent_collaborative:positive","points":2},{"pole":"direct_indirect:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('725bc740-a472-4c9e-9cf9-033dfc7d3132', '58812704-45a7-48c0-87e6-8e7ad42b49fe', 2, '"Different how? Did I do something?"', 'Apparently, the family feedback department has opened an investigation. Please submit examples.', '[{"pole":"curious_decisive:positive","points":2},{"pole":"reflective_reactive:positive","points":2},{"pole":"self_secure_reassurance:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('3bc331ae-2deb-4989-b9ab-d42374704cf5', '58812704-45a7-48c0-87e6-8e7ad42b49fe', 3, 'Start making myself smaller so nobody feels left behind.', 'Apparently, you''ve achieved personal growth and immediately attempted to fold it into the overhead compartment.', '[{"pole":"boundary_holding_approval_seeking:negative","points":3},{"pole":"duty_first_self_preserving:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('5ea36a64-c5a8-4f34-837a-5da4c52045b2', '58812704-45a7-48c0-87e6-8e7ad42b49fe', 4, '"I''m still me. I just have different priorities."', 'Apparently, you''ve updated your priorities, not your personality. Some people are just upset they no longer have administrator access.', '[{"pole":"boundary_holding_approval_seeking:positive","points":2},{"pole":"direct_indirect:positive","points":2},{"pole":"reflective_reactive:positive","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('14e1c837-6107-4f41-bacf-5c36b04c8517', 'Your partner tells you, "I feel like I can''t do anything right with you."', 'Unsorted', 'Approved', 'private');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('23367da9-3b5d-4fc5-a9f3-04a310e393c9', '14e1c837-6107-4f41-bacf-5c36b04c8517', 1, '"What am I doing that makes you feel that way?"', 'Apparently, you''ve paused the argument to request actual feedback. Emotional quality assurance is officially underway.', '[{"pole":"reflective_reactive:positive","points":3},{"pole":"curious_decisive:positive","points":2},{"pole":"repair_punishing:positive","points":2},{"pole":"perspective_taking_self_referencing:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('0815be66-340b-4215-afdd-9338ec22ef19', '14e1c837-6107-4f41-bacf-5c36b04c8517', 2, '"Maybe if you actually DID something right, we wouldn''t be here."', 'Apparently, your partner brought feelings to the conversation and you brought a performance evaluation. Nobody''s getting a raise.', '[{"pole":"accountability_defensiveness:negative","points":3},{"pole":"tactful_blunt:negative","points":3},{"pole":"reflective_reactive:negative","points":2},{"pole":"perspective_taking_self_referencing:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('dfd56122-f27e-4df5-aab7-7e6b3d341ae7', '14e1c837-6107-4f41-bacf-5c36b04c8517', 3, '"I''m sorry you feel that way. I really am trying."', 'Apparently, you''ve offered an emotional olive branch. Whether anybody accepts it remains under negotiation.', '[{"pole":"repair_punishing:positive","points":2},{"pole":"vulnerable_armored:positive","points":2},{"pole":"conflict_peacekeeping:negative","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('f8a95b2d-a714-47dd-8876-fece1afa06f0', '14e1c837-6107-4f41-bacf-5c36b04c8517', 4, '"Then tell me what you need instead of making me guess."', 'Apparently, you''ve requested instructions, examples, and possibly a user manual. The guessing department is closed.', '[{"pole":"direct_indirect:positive","points":3},{"pole":"accountability_defensiveness:positive","points":2},{"pole":"supportive_challenging:negative","points":2},{"pole":"practical_idealistic:positive","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('30245103-ae5a-4942-b498-25bb6cd2e985', 'You discover your partner has been telling their friends about your private arguments.', 'Unsorted', 'Approved', 'private');
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('f893e3ee-5190-4b4c-9879-793fc0b90eb2', '30245103-ae5a-4942-b498-25bb6cd2e985', 1, '"Our problems aren''t group-chat entertainment. We need boundaries."', 'Apparently, your relationship has a privacy policy, and somebody just shared the password with the entire neighborhood.', '[{"pole":"boundary_holding_approval_seeking:positive","points":3},{"pole":"private_open:positive","points":3},{"pole":"direct_indirect:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('7ba995a1-bf84-411a-a9f0-04672d34f337', '30245103-ae5a-4942-b498-25bb6cd2e985', 2, '"I get needing advice, but why didn''t you tell me?"', 'Apparently, you understand the need for outside counsel. You just weren''t expecting to discover an entire advisory board.', '[{"pole":"perspective_taking_self_referencing:positive","points":3},{"pole":"repair_punishing:positive","points":2},{"pole":"direct_indirect:positive","points":2},{"pole":"vulnerable_armored:positive","points":1}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('e36b0005-7028-4847-a2c9-e454e2a10187', '30245103-ae5a-4942-b498-25bb6cd2e985', 3, 'Call my friends and tell them EVERYTHING. Since we''re sharing.', 'Apparently, you''ve responded to a privacy breach by launching your own competing podcast. Episode one is already trending.', '[{"pole":"repair_punishing:negative","points":3},{"pole":"reflective_reactive:negative","points":3},{"pole":"gives_freely_keeps_score:negative","points":2},{"pole":"conflict_peacekeeping:positive","points":2}]'::jsonb);
insert into public.daily_options (id, question_id, "position", label, apparently_feedback, pole_personality_effects) values ('763f41ee-26b7-4b80-977f-cfb504d766ac', '30245103-ae5a-4942-b498-25bb6cd2e985', 4, '"I don''t care who you talk to, but don''t tell only your side."', 'Apparently, you''re not against relationship witnesses. You just want the court to hear from both parties.', '[{"pole":"accountability_defensiveness:positive","points":3},{"pole":"practical_idealistic:positive","points":2},{"pole":"boundary_holding_approval_seeking:positive","points":2},{"pole":"perspective_taking_self_referencing:positive","points":1}]'::jsonb);
insert into public.daily_questions (id, prompt, category, status, room) values ('15f4b8fe-6612-4683-a87c-13783fef193b', 'You can bring ONE fictional villain to Thanksgiving dinner. Who''s getting a plate?', 'Unsorted', 'Approved', 'public');
